{"path": "/tmp/sv-8d4dc2f0d0274812b73a75e37b63ade3/RecipeCommunity/Services/RecipeService.cs", "file_text": "using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Dictionary<int, List<int>> _ratings = new();
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
                Steps = "Preheat oven to 475°F (245°C).\nRoll out dough on a floured surface.\nSpread crushed tomatoes over the dough.\nTear mozzarella and distribute evenly.\nBake for 10–12 minutes until crust is golden.\nTop with fresh basil and a drizzle of olive oil." },
            new() { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
                Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger\nOnion",
                Steps = "Marinate chicken in yogurt and spices for 1 hour.\nGrill or pan-sear chicken until charred.\nSauté onion, garlic, and ginger in a pot.\nAdd tomato sauce and remaining spices; simmer 15 min.\nAdd cream and cooked chicken; simmer 10 min.\nServe with basmati rice or naan." },
            new() { Id = 3, Title = "Beef Tacos", Category = "Mexican",
                Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
                Steps = "Brown ground beef in a skillet over medium heat.\nAdd taco seasoning and water; simmer 5 min.\nWarm tortillas in a dry pan.\nAssemble tacos with beef, lettuce, tomato, and cheese.\nTop with sour cream and salsa." },
            new() { Id = 4, Title = "Pad Thai", Category = "Asian",
                Ingredients = "Rice noodles\nShrimp or tofu\nEgg\nBean sprouts\nGreen onions\nPeanuts\nLime\nFish sauce\nTamarind paste\nSugar",
                Steps = "Soak rice noodles in warm water for 20 min; drain.\nMix tamarind paste, fish sauce, and sugar for the sauce.\nStir-fry shrimp or tofu; set aside.\nScramble egg in the same pan.\nAdd noodles and sauce; toss until coated.\nAdd bean sprouts and protein; garnish with peanuts, green onion, and lime." },
            new() { Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
                Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract\nPinch of salt",
                Steps = "Preheat oven to 425°F (220°C). Grease ramekins.\nMelt chocolate and butter together.\nWhisk eggs and sugar until thick.\nFold chocolate mixture into eggs; add flour, vanilla, salt.\nPour into ramekins and bake 12–14 min.\nInvert onto plates and serve immediately." },
            new() { Id = 6, Title = "Caesar Salad", Category = "Salads",
                Ingredients = "Romaine lettuce\nParmesan cheese\nCroutons\nCaesar dressing\nLemon juice\nAnchovy paste\nGarlic",
                Steps = "Wash and chop romaine lettuce.\nWhisk together dressing, lemon juice, anchovy paste, and garlic.\nToss lettuce with dressing.\nTop with shaved Parmesan and croutons.\nServe immediately." },
            new() { Id = 7, Title = "Spaghetti Carbonara", Category = "Italian",
                Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper",
                Steps = "Cook spaghetti in salted boiling water until al dente.\nCrisp guanciale in a skillet.\nWhisk eggs and Pecorino together.\nDrain pasta, reserving some water.\nToss hot pasta with guanciale, then egg mixture off heat.\nAdd pasta water as needed; season with black pepper." },
            new() { Id = 8, Title = "Mango Sticky Rice", Category = "Desserts",
                Ingredients = "Sticky (glutinous) rice\nCoconut milk\nSugar\nSalt\nRipe mango",
                Steps = "Soak sticky rice for 4 hours; steam for 20 min.\nHeat coconut milk with sugar and salt.\nPour half the coconut sauce over cooked rice; let absorb.\nSlice ripe mango.\nServe rice with mango slices and remaining coconut sauce." },
        };
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public List<RecipeCategory> GetCategories()
    {
        return new List<RecipeCategory>
        {
            new() { Name = "Italian", Icon = "🍝", Description = "Pasta, pizza, and Mediterranean classics" },
            new() { Name = "Mexican", Icon = "🌮", Description = "Tacos, burritos, and bold flavors" },
            new() { Name = "Indian", Icon = "🍛", Description = "Rich curries and aromatic spices" },
            new() { Name = "Asian", Icon = "🍜", Description = "Stir-fries, noodles, and umami" },
            new() { Name = "Desserts", Icon = "🍰", Description = "Sweet treats and baked goods" },
            new() { Name = "Salads", Icon = "🥗", Description = "Fresh, healthy, and colorful" },
        };
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;

        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);
        recipe.RatingCount = _ratings[recipeId].Count;
        recipe.AverageRating = _ratings[recipeId].Average();
    }
}
"}

