                       placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add wet ingredients and stir." />
        <ValidationMessage For="() => model.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-success">Submit Recipe</button>
    <a href="/" class="btn btn-outline-secondary ms-2">Cancel</a>
</EditForm>

@code {
    private Recipe model = new();
    private string? successMessage;

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(model);
        successMessage = $"'{model.Title}' has been submitted! 🎉";
        model = new Recipe();
    }
}
